customer_success_rates = Customers.CALCULATE(
    customer_name=name,
    total_transactions=COUNT(transactions_made),
    successful_transactions=COUNT(transactions_made.WHERE(LOWER(status) == 'success'))
).WHERE(
    total_transactions >= 50
).CALCULATE(
    customer_name=customer_name,
    success_rate=100.0 * successful_transactions / total_transactions
).ORDER_BY(success_rate.ASC())

result = Broker.CALCULATE(
    num_customers = COUNT(
        Customers.WHERE(
            ENDSWITH(email, '.com') & 
            HAS(
                transactions_made.WHERE(
                    CONTAINS(ticker.symbol, 'AMZN') |
                    CONTAINS(ticker.symbol, 'AAPL') |
                    CONTAINS(ticker.symbol, 'GOOGL') |
                    CONTAINS(ticker.symbol, 'META') |
                    CONTAINS(ticker.symbol, 'NFLX')
                )
            ) == 1
        )
    )
)

tac_by_country = Customers.WHERE(
    (LOWER(status) == 'active') & (join_date >= '2023-01-01')
).PARTITION(
    name='country_groups', by=(country)
).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)
